public static boolean computeWithBinarySearch(int[][] matrix, int target) {
    if (matrix.length == 0 || matrix[0].length == 0) return false;

    int m = matrix.length;
    int n = matrix[0].length;
    int left = 0;
    int right = m * n - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int midValue = matrix[mid / n][mid % n];

        if (midValue == target) {
            return true;
        } else if (midValue < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return false;
}

public static boolean computeWithTwoBinarySearches(int[][] matrix, int target) {
    if (matrix.length == 0 || matrix[0].length == 0) return false;

    int m = matrix.length;
    int n = matrix[0].length;

    // Find the row
    int top = 0, bottom = m - 1;
    while (top < bottom) {
        int mid = top + (bottom - top) / 2;
        if (matrix[mid][n - 1] < target) {
            top = mid + 1;
        } else {
            bottom = mid;
        }
    }

    // Search in the row
    int left = 0, right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (matrix[top][mid] == target) {
            return true;
        } else if (matrix[top][mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return false;
}

public static boolean computeWithLinearSearch(int[][] matrix, int target) {
    for (int[] row : matrix) {
        for (int value : row) {
            if (value == target) {
                return true;
            }
        }
    }
    return false;
}
